[CmdletBinding()]
param([switch]$ConfirmReal,[switch]$RunSyntheticTests,[string]$TargetPath='C:\Dev\sumi-guard\demo\Invoke-SumiGuardManagedPowerShellAssessmentDemo.ps1',[string]$DemoDataPath='C:\Dev\sumi-guard\.demo-data')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$script:TargetStartCount=0
function Get-FixedDiagnostic([string]$Stage,[Exception]$Exception){[pscustomobject]@{stage=$Stage;exception_type=$Exception.GetType().FullName;hresult=('0x{0:X8}' -f ($Exception.HResult -band 0xffffffff))}}
function Get-ProjectSnapshot([switch]$ForceFailure){if($ForceFailure){throw [InvalidOperationException]::new('synthetic')};$files=@([IO.FileInfo]::new($TargetPath));$files+=@([IO.Directory]::GetFiles($DemoDataPath,'*',[IO.SearchOption]::AllDirectories)|Sort-Object|ForEach-Object{[IO.FileInfo]::new($_)});$records=@();foreach($file in $files){if(-not $file.Exists){throw [IO.FileNotFoundException]::new('missing')};$stream=[IO.File]::OpenRead($file.FullName);try{$sha=[Security.Cryptography.SHA256]::Create();try{$hash=([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','')}finally{$sha.Dispose()}}finally{$stream.Dispose()};$records+=[pscustomobject]@{path=$file.FullName;value="$($file.Length):$hash"}};return @($records)}
function Get-SnapshotDiffCount($Before,$After){$l=@{};$r=@{};foreach($x in $Before){$l[$x.path]=$x.value};foreach($x in $After){$r[$x.path]=$x.value};return @($l.Keys+$r.Keys|Sort-Object -Unique|Where-Object{-not $l.ContainsKey($_)-or -not $r.ContainsKey($_)-or $l[$_]-ne $r[$_]}).Count}
function Invoke-HarmlessChild([string]$Name){$code=switch($Name){'normal_json'{'[Console]::Out.WriteLine(''{"status":"ok"}'')'}'invalid_json'{'[Console]::Out.WriteLine(''invalid'')'}'empty_output'{''}'multiple_reports'{'[Console]::Out.WriteLine(''{"n":1}'');[Console]::Out.WriteLine(''{"n":2}'')'}'nonzero_exit'{'[Console]::Out.WriteLine(''{"status":"ok"}'');exit 7'}'parse_exception'{'[Console]::Out.WriteLine(''{"status":"ok"}'')'}'post_snapshot_exception'{'[Console]::Out.WriteLine(''{"status":"ok"}'')'}'parallel_capture'{'[Console]::Out.WriteLine(''safe-stdout'');[Console]::Error.WriteLine(''safe-stderr'')'}default{throw [ArgumentOutOfRangeException]::new('Name')}};$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe';$psi.Arguments='-NoProfile -NonInteractive -EncodedCommand '+[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($code));$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.CreateNoWindow=$true;$p=[Diagnostics.Process]::new();$p.StartInfo=$psi;$null=$p.Start();$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$p.WaitForExit();[pscustomobject]@{exit_code=$p.ExitCode;stdout=$ot.GetAwaiter().GetResult();stderr=$et.GetAwaiter().GetResult()}}
function Invoke-SyntheticCase($D,$Before){$c=Invoke-HarmlessChild $D.name;$im=$true;[Console]::Out.WriteLine(('IMMEDIATE case={0} exit={1} stdout_nonempty={2} stderr_nonempty={3}' -f $D.name,$c.exit_code,($c.stdout.Length -gt 0),($c.stderr.Length -gt 0)));$postAttempt=$false;$diag=$null;try{if($D.force_parse){throw [FormatException]::new('synthetic')};if([string]::IsNullOrWhiteSpace($c.stdout)){throw [FormatException]::new('synthetic')};$reports=@($c.stdout|ConvertFrom-Json -ErrorAction Stop);if($reports.Count -ne 1){throw [FormatException]::new('synthetic')};$parse='PARSE_OK'}catch{$parse='PARSE_SAFE_FAILURE';$diag=Get-FixedDiagnostic 'parse' $_.Exception};try{$postAttempt=$true;$after=Get-ProjectSnapshot -ForceFailure:$D.force_post;$post=if((Get-SnapshotDiffCount $Before $after) -eq 0){'POST_OK'}else{'POST_DIFF'}}catch{$post='POST_SAFE_FAILURE';if($null -eq $diag){$diag=Get-FixedDiagnostic 'post_snapshot' $_.Exception}};$actual=if($D.name -eq 'parallel_capture'){if(($c.stdout.Length -gt 0) -and ($c.stderr.Length -gt 0)){"CAPTURE_BOTH_$parse`_$post"}else{"CAPTURE_MISSING_$parse`_$post"}}elseif($D.name -eq 'nonzero_exit'){"EXIT_$($c.exit_code)_$parse`_$post"}else{"$parse`_$post"};$pass=($actual -eq $D.expected_state -and $im -and $postAttempt);[pscustomobject]@{case_name=$D.name;expected_state=$D.expected_state;actual_state=$actual;result=if($pass){'PASS'}else{'FAIL'};immediate_summary_generated=$im;post_reconciliation_attempted=$postAttempt;diagnostic=$diag}}
try{$before=Get-ProjectSnapshot}catch{[pscustomobject]@{setup_diagnostic=Get-FixedDiagnostic 'pre_snapshot' $_.Exception;target_start_count=0}|ConvertTo-Json -Compress;exit 2}
if(-not $RunSyntheticTests){[pscustomobject]@{mode='idle';target_start_count=0;real_confirmation_gate_open=$false}|ConvertTo-Json -Compress;exit 0}
$defs=@(@{name='normal_json';expected_state='PARSE_OK_POST_OK';force_parse=$false;force_post=$false},@{name='invalid_json';expected_state='PARSE_SAFE_FAILURE_POST_OK';force_parse=$false;force_post=$false},@{name='empty_output';expected_state='PARSE_SAFE_FAILURE_POST_OK';force_parse=$false;force_post=$false},@{name='multiple_reports';expected_state='PARSE_SAFE_FAILURE_POST_OK';force_parse=$false;force_post=$false},@{name='nonzero_exit';expected_state='EXIT_7_PARSE_OK_POST_OK';force_parse=$false;force_post=$false},@{name='parse_exception';expected_state='PARSE_SAFE_FAILURE_POST_OK';force_parse=$true;force_post=$false},@{name='post_snapshot_exception';expected_state='PARSE_OK_POST_SAFE_FAILURE';force_parse=$false;force_post=$true},@{name='parallel_capture';expected_state='CAPTURE_BOTH_PARSE_SAFE_FAILURE_POST_OK';force_parse=$false;force_post=$false})
$results=@($defs|ForEach-Object{Invoke-SyntheticCase $_ $before});$all=@($results|Where-Object{$_.result -ne 'PASS'}).Count -eq 0;[pscustomobject]@{synthetic_test_count=$results.Count;synthetic_all_passed=$all;target_start_count=0;real_confirmation_gate_open=($ConfirmReal -and $all);results=$results}|ConvertTo-Json -Depth 7;if(-not $all){exit 1};exit 0
